cd documents; python3 - <<EOF
import zipfile,re
for f in ["closing-checklist.docx","credit-agreement.docx","officers-compliance-certificate.docx"]:
    z=zipfile.ZipFile(f); print(f,[n for n in z.namelist() if not n.startswith("word/theme")])
    for n in z.namelist():
        if re.search(r"(header|footer|comments|footnotes)",n):
            t=re.sub(r"<[^>]+>"," ",z.read(n).decode()); t=re.sub(r"\s+"," ",t); print(" ",n,":",t[:500])
    d=z.read("word/document.xml").decode()
    print("  vanish:",d.count("<w:vanish"),"ins:",d.count("<w:ins "),"del:",d.count("<w:del "))
EOF
